insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-08','nieuw','Inkoop','Inkoopfacturen staan nu in EVA',
   'Onder Financieel vind je het nieuwe onderdeel Inkoop met alle inkoopfacturen uit Bouw7 bij elkaar: leverancier, project, bewakingscode, bedrag excl. en incl. btw, vervaldatum, de opmerking uit Bouw7 en wie de factuur nog moet goedkeuren. Het tabblad "Te accorderen door mij" laat met een teller zien hoeveel facturen er op jou wachten. Klik op een factuurnummer en het document opent in een venster; klik op de regel en je ziet in het zijpaneel de volledige goedkeuringsketen met de toelichting van elke goedkeurder. Je kunt er ook een eigen notitie bij zetten. Goedkeuren doe je voorlopig nog in Bouw7; het paneel brengt je met één klik op de juiste plek. Wat je ziet hangt af van je rechten: sommige collega''s zien alleen de facturen die bij een project horen, andere ook de facturen voor bedrijfskosten zoals abonnementen en leasing.'),
  ('2026-09-08','nieuw','Inkoop','Aanvinken welke facturen betaald mogen worden',
   'De directie kan bij een goedgekeurde factuur aanvinken dat hij mee mag in de eerstvolgende betaling. Op het tabblad Betalen staat vervolgens de lijst voor wie de betaling uitvoert, met alle gegevens die daarvoor nodig zijn en een export naar Excel. Facturen die nog ter goedkeuring liggen kunnen niet worden aangevinkt.');
